"use strict";(self.webpackChunkpos_globalpay_doc=self.webpackChunkpos_globalpay_doc||[]).push([[622],{2387(e,a,t){t.r(a),t.d(a,{_pageData:()=>o,default:()=>n});var r=t(641);const o=JSON.parse('{"path":"/getting-started/overview.html","title":"System Overview","lang":"en-US","frontmatter":{},"git":{},"filePathRelative":"getting-started/overview.md"}'),s={name:"overview.md"},n=(0,t(6262).A)(s,[["render",function(e,a,t,o,s,n){return(0,r.uX)(),(0,r.CE)("div",null,[...a[0]||(a[0]=[(0,r.Fv)('<h1 id="system-overview" tabindex="-1"><a class="header-anchor" href="#system-overview"><span>System Overview</span></a></h1><p><strong>POS Globalpay Terminal Payment for WooCommerce</strong> provides a physical card reader payment bridge designed specifically for Webkul WooCommerce Point of Sale (POS).</p><hr><h2 id="how-it-works" tabindex="-1"><a class="header-anchor" href="#how-it-works"><span>How It Works</span></a></h2><ol><li><strong>Cart Selection</strong>: The POS cashier adds items to the cart and selects <strong>POS Global Pay Terminal</strong> at checkout.</li><li><strong>Socket Request</strong>: The POS interface sends a secure JSON payload to the local Node.js WebSocket bridge server.</li><li><strong>Hardware Prompt</strong>: The Node server forwards the command over local TCP socket to the connected physical Globalpay card reader, Android Terminal App, or UPA Emulator.</li><li><strong>Customer Card Swipe / PIN</strong>: The customer inserts/taps their card and inputs their secret PIN on the physical terminal.</li><li><strong>Gateway Authorization</strong>: The terminal processes payment with Globalpay gateway servers.</li><li><strong>Order Upgrade</strong>: Upon receiving the approval callback, WooCommerce upgrades the order status to <code>Completed</code> and attaches transaction metadata audit logs.</li></ol><p><img src="/pos-globalpay-terminal-payment/images/pos-checkout-upa-emulator.png" alt="POS Cashier Screen with UPA Emulator"></p><hr><h2 id="key-architectural-advantages" tabindex="-1"><a class="header-anchor" href="#key-architectural-advantages"><span>Key Architectural Advantages</span></a></h2><ul><li><strong>Zero Manual Data Entry</strong>: Eliminates cashier keying errors by transmitting exact cart totals to the terminal automatically.</li><li><strong>Low Latency</strong>: Local socket bridge ensures sub-second response times between cashier screen and card reader.</li><li><strong>Encrypted Local Transport</strong>: Supports TLS/SSL certificate encryption for socket connections.</li><li><strong>HPOS Ready</strong>: Built ground-up to support WooCommerce High-Performance Order Storage database structures.</li></ul>',9)])])}]])}}]);